"""Write the formal annotation view without legacy progress-label columns."""
import json,hashlib
from datetime import datetime,timezone
import numpy as np,pandas as pd
r=PROJECT_ROOT/'runs/20261106_v7_publication_marker_annotation_v1';c=r/'stage_c4_harmonized_identity_freeze';d=r/'stage_d4_harmonized_marker_evidence';o=r/'stage_f4_formal_annotation_release';o.mkdir(exist_ok=False)
assert json.loads((c/'independent_freeze_audit.json').read_text())['status']=='PASS';assert json.loads((d/'independent_naming_marker_audit.json').read_text())['status']=='PASS';assert json.loads((r/'stage_e4_release_retention/complete.json').read_text())['status']=='PASS_retention_accounting'
source=c/'marker_identity_frozen_cells_PRIVATE.pkl.gz';f=pd.read_pickle(source);out=pd.DataFrame(index=f.index);out.index.name='cell_id';out['final_annotation']=f.final_annotation;out['major_cell_type']=f.final_parent;out['representative_markers']=f.representative_markers;out['annotation_resolution']='major_identity_plus_markers';out['annotation_version']='V7_marker_identity_20261106_v3';out['evidence_basis']=f.freeze_basis
for col in ['raw_IFN_programme_positive','raw_cycling_programme_positive','raw_heat_shock_programme_positive']:out[col]=f[col]
for col in f.columns:
 if col.startswith('frozen_') and ('malignan' in col or 'evidence_version' in col):out[col.removeprefix('frozen_')]=f[col]
for col in out.select_dtypes(include=object):out[col]=out[col].astype('category')
policy=json.loads((r/'identity_policy_v2.json').read_text());assert out.final_annotation.notna().all() and not out.final_annotation.astype(str).str.contains('|'.join(policy['final_label_prohibited_words']),case=False,regex=True).any();assert not {'frozen_label','legacy_label','old_label','frozen_parent','previous_working_parent','freeze_status','diagnostic_group','diagnostic_cluster'}.intersection(out.columns)
p=o/'annotation_frozen_V7_marker_20261106_v3_PRIVATE.pkl.gz';out.to_pickle(p,compression={'method':'gzip','compresslevel':1});back=pd.read_pickle(p);assert out.index.equals(back.index) and out.columns.equals(back.columns)
for col in out:
 if isinstance(out[col].dtype,pd.CategoricalDtype):assert out[col].cat.categories.equals(back[col].cat.categories) and np.array_equal(out[col].cat.codes.to_numpy(),back[col].cat.codes.to_numpy())
 else:
  x=out[col].astype(object).to_numpy();y=back[col].astype(object).to_numpy();na=pd.isna(x);assert np.array_equal(na,pd.isna(y)) and np.array_equal(x[~na],y[~na])
out.to_csv(o/'annotation_frozen_V7_marker_20261106_v3_PRIVATE.tsv.gz',sep='\t',compression={'method':'gzip','compresslevel':1},na_rep='NA');position=0
for chunk in pd.read_csv(o/'annotation_frozen_V7_marker_20261106_v3_PRIVATE.tsv.gz',sep='\t',usecols=['cell_id','final_annotation','major_cell_type'],chunksize=100000):
 n=len(chunk);expect=out.iloc[position:position+n];assert np.array_equal(chunk.cell_id.to_numpy(),expect.index.to_numpy());assert np.array_equal(chunk.final_annotation.to_numpy(),expect.final_annotation.astype(str).to_numpy());assert np.array_equal(chunk.major_cell_type.to_numpy(),expect.major_cell_type.astype(str).to_numpy());position+=n
assert position==len(out)
out.groupby(['major_cell_type','final_annotation','representative_markers'],observed=True,dropna=False).size().rename('n_cells').reset_index().to_csv(o/'formal_frozen_label_counts.tsv',sep='\t',index=False)
sourceproof=json.loads((r/'stage_c2_exact_audit_resume/independent_serialized_axis_audit.json').read_text());assert len(out)==sourceproof['n_frozen'];assert set(out.final_annotation.astype(str))==set(pd.read_csv(d/'frozen_label_identity_state_summary.tsv',sep='\t').final_annotation)
receipt={'status':'PASS_formal_annotation_freeze_export_and_exact_readback','UTC':datetime.now(timezone.utc).isoformat(),'annotation_version':'V7_marker_identity_20261106_v3','n_frozen_cells':len(out),'n_final_label_values':out.final_annotation.nunique(),'n_major_cell_types':out.major_cell_type.nunique(),'n_original_axis':sourceproof['n_all_axis'],'n_QC_keep_outside_identity_freeze':sourceproof['n_QC_keep_outside_identity_freeze'],'identity_column':'final_annotation','legacy_progress_label_columns_present_in_formal_view':False,'all_identity_labels_free_of_progress_placeholders':True,'all_CNV_columns_and_state_positive_flags_preserved_separately':True,'private_TSV_complete_stream_readback':True,'identity_granularity':'major-plus-marker; no new fine subtype or normality/function claim','original_V7_history':'Preserved separately in stage_c4_harmonized_identity_freeze/annotation_all_cells_with_release_status_PRIVATE.pkl.gz; not a formal identity column.','all_atlas_publication_acceptance':False,'source_frozen_identity_file_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'files':[{'name':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in o.iterdir() if p.is_file()]};(o/'FORMAL_FREEZE_ACCEPTANCE.json').write_text(json.dumps(receipt,indent=2));print(json.dumps({k:v for k,v in receipt.items() if k!='files'}))
